-- 144_provas_publicas_missiologia_etica.sql
-- 02/11/2026, pedido do Joaquim: "fazer as provas e ja disponibilizar no portal".
-- Mesma rotina de 123 (Escatologia) e 127 (Lideranca Crista): alimenta provas_publicas /
-- provas_publicas_questoes (link publico + CPF, prova FIXA). Nao cria tabela, nao apaga nada.
--   Missiologia (Curso Medio): Testes 1, 2 e 3  -> /prova-publica/missiologia-teste-1..3
--   Etica Crista (Curso Basico): Testes 1 a 4 -> /prova-publica/etica-crista-teste-1..4
-- 7 testes x 20 questoes. Gabarito = PDFs oficiais do CETADP (GABARITO Missiologia A5 /
-- GABARITO ETICA CRISTA, secao "TESTES PARCIAIS"), conferido contra o texto de cada prova.
-- Etica Teste 1 tem 5 questoes de multipla escolha (a-d): o modulo so tem CERTO_ERRADO e
-- ASSOCIACAO_COLUNAS, entao elas entram como ASSOCIACAO_COLUNAS (lista suspensa; o valor e a 1a letra
-- da opcao e a correcao ignora maiuscula/minuscula, entao "b" do gabarito vale). Sem mudar codigo.
-- PENDENTES: Missiologia Testes 4 e 5 (so veio o gabarito). Entram depois com novos slugs.
-- lesson_id: buscado pelo titulo da materia (cada banco tem o seu UUID); fica null se nao existir.
-- Idempotente (on conflict do nothing). Reversao: delete from provas_publicas where slug like
-- 'missiologia-teste-%' or slug like 'etica-crista-teste-%' (questoes saem em cascata; so antes
-- de qualquer aluno responder).

insert into public.provas_publicas (materia, titulo, numero_teste, slug, lesson_id) values
  ('Missiologia', 'Teste 1 - Lições 1 e 2', 1, 'missiologia-teste-1', (select id from public.lessons where title = 'Missiologia' order by created_at limit 1)),
  ('Missiologia', 'Teste 2 - Lições 3 e 4', 2, 'missiologia-teste-2', (select id from public.lessons where title = 'Missiologia' order by created_at limit 1)),
  ('Missiologia', 'Teste 3 - Lições 5 e 6', 3, 'missiologia-teste-3', (select id from public.lessons where title = 'Missiologia' order by created_at limit 1)),
  ('Ética Cristã', 'Teste 1 - Lições 1 e 2', 1, 'etica-crista-teste-1', (select id from public.lessons where title = 'Ética Cristã' order by created_at limit 1)),
  ('Ética Cristã', 'Teste 2 - Lições 3 e 4', 2, 'etica-crista-teste-2', (select id from public.lessons where title = 'Ética Cristã' order by created_at limit 1)),
  ('Ética Cristã', 'Teste 3 - Lições 5 e 6', 3, 'etica-crista-teste-3', (select id from public.lessons where title = 'Ética Cristã' order by created_at limit 1)),
  ('Ética Cristã', 'Teste 4 - Lições 7 e 8', 4, 'etica-crista-teste-4', (select id from public.lessons where title = 'Ética Cristã' order by created_at limit 1))
on conflict (slug) do nothing;

