from (values
  ('missiologia-teste-1', 1, 'CERTO_ERRADO', 'Missiologia no grego se equivale a Missionario.', null::jsonb, 'E'),
  ('missiologia-teste-1', 2, 'CERTO_ERRADO', 'O reino de Deus é um processo de libertação total do homem da maldição do pecado.', null::jsonb, 'C'),
  ('missiologia-teste-1', 3, 'CERTO_ERRADO', 'Só faz missão quem ama, e Deus é a fonte de amor.', null::jsonb, 'C'),
  ('missiologia-teste-1', 4, 'CERTO_ERRADO', 'Missão não compreende aquele que envia.', null::jsonb, 'E'),
  ('missiologia-teste-1', 5, 'CERTO_ERRADO', 'Chamamos de Janela 10/40, a região que está localizada entre os paralelos 10/40 do globo terrestre.', null::jsonb, 'C'),
  ('missiologia-teste-1', 6, 'CERTO_ERRADO', 'A meta e a sublime tarefa dos Evangelhos delegada aos anjos é de alcançar o mundo inteiro.', null::jsonb, 'E'),
  ('missiologia-teste-1', 7, 'CERTO_ERRADO', 'Missões transculturais observa que cada povo tem sua cultura.', null::jsonb, 'C'),
  ('missiologia-teste-1', 8, 'CERTO_ERRADO', 'Quando o povo crê em Cristo e o aceita, gosta de fazê-lo sem ter de cruzar barreiras sociais, linguísticas ou sociais.', null::jsonb, 'C'),
  ('missiologia-teste-1', 9, 'CERTO_ERRADO', 'O Missiólogo é aquele que se dedica ao estudo, se dedica em pesquisar sobre missões.', null::jsonb, 'C'),
  ('missiologia-teste-1', 10, 'CERTO_ERRADO', 'Missionário é o que fica, é aquele que propriamente fica no campo de forma mais atuante.', null::jsonb, 'E'),
  ('missiologia-teste-1', 11, 'CERTO_ERRADO', 'O termo "missão" ganhou notoriedade entre os cristãos nos anos 70.', null::jsonb, 'E'),
  ('missiologia-teste-1', 12, 'CERTO_ERRADO', 'Em um conceito mais teológico missão nada mais é do que a propagação da fé.', null::jsonb, 'C'),
  ('missiologia-teste-1', 13, 'CERTO_ERRADO', 'O mundo das missões e evangelismo são áreas de atuação profundamente enraizada nas tradições de todas as vertentes religiosas.', null::jsonb, 'C'),
  ('missiologia-teste-1', 14, 'CERTO_ERRADO', 'Missões tem suas raízes na "Grande Comissão" ensinada por Paulo.', null::jsonb, 'E'),
  ('missiologia-teste-1', 15, 'CERTO_ERRADO', 'Evangelizar é o componente fundamental das missões e envolve a propagação da "Boa Nova".', null::jsonb, 'C'),
  ('missiologia-teste-1', 16, 'CERTO_ERRADO', 'Não é objetivo do evangelismo influenciar a crença e a prática religiosa das pessoas.', null::jsonb, 'E'),
  ('missiologia-teste-1', 17, 'CERTO_ERRADO', 'Missões e o evangelismo contribuem e muito para a propagação de valores positivos, como a transformação de muitas vidas.', null::jsonb, 'C'),
  ('missiologia-teste-1', 18, 'CERTO_ERRADO', 'O mundo de missões e evangelismo é um território complexo e multifacetado.', null::jsonb, 'C'),
  ('missiologia-teste-1', 19, 'CERTO_ERRADO', 'O evangelismo desempenha um papel fundamental na propalação da fé em várias religiões.', null::jsonb, 'C'),
  ('missiologia-teste-1', 20, 'CERTO_ERRADO', 'A igreja não precisa se preocupar com o chamado missionário.', null::jsonb, 'E'),
  ('missiologia-teste-2', 1, 'CERTO_ERRADO', 'A Grande Comissão é um termo que se refere a uma ordem dada por Jesus Cristo aos seus discípulos.', null::jsonb, 'C'),
  ('missiologia-teste-2', 2, 'CERTO_ERRADO', 'A Ressurreição é a base para a missão evangelística da igreja cristã ao longo dos séculos.', null::jsonb, 'E'),
  ('missiologia-teste-2', 3, 'CERTO_ERRADO', 'As missões cristãs são uma resposta à chamada de Jesus para fazer discípulos de todas as nações.', null::jsonb, 'C'),
  ('missiologia-teste-2', 4, 'CERTO_ERRADO', 'A igreja é um local, que pode ser um salão ou prédio que abriga as pessoas.', null::jsonb, 'E'),
  ('missiologia-teste-2', 5, 'CERTO_ERRADO', 'A igreja possui três ministérios, sendo o ministério com Deus, com os Cristãos e com o Mundo.', null::jsonb, 'C'),
