  ('etica-crista-teste-2', 3, 'CERTO_ERRADO', 'Fomos credenciados por Deus para julgar este mundo.', null::jsonb, 'C'),
  ('etica-crista-teste-2', 4, 'CERTO_ERRADO', 'Não basta dizer que isso ou aquilo é imoral, é preciso deter o avanço da imoralidade.', null::jsonb, 'C'),
  ('etica-crista-teste-2', 5, 'CERTO_ERRADO', 'Na área da ética cristã comportamento não harmoniza-se como a vontade de Deus.', null::jsonb, 'E'),
