  ('etica-crista-teste-2', 7, 'CERTO_ERRADO', 'A vontade de Deus abrange todas as áreas da vida de seus filhos.', null::jsonb, 'C'),
  ('etica-crista-teste-2', 8, 'CERTO_ERRADO', 'Para conhecer a vontade de Deus é indispensável que o homem passe por uma metamorfose espiritual.', null::jsonb, 'C'),
  ('etica-crista-teste-2', 9, 'CERTO_ERRADO', 'Ética Cristã e Teologia nem sempre andam juntas.', null::jsonb, 'E'),
  ('etica-crista-teste-2', 10, 'CERTO_ERRADO', 'O caráter, a consciência e a vontade são questões essenciais que envolvem a psiquê do indivíduo.', null::jsonb, 'C'),
  ('etica-crista-teste-2', 11, 'CERTO_ERRADO', 'Nas epístolas, o apóstolo Paulo dá um ensino específico como norma de vida somente aos cristãos da sua época.', null::jsonb, 'E'),
  ('etica-crista-teste-2', 12, 'CERTO_ERRADO', 'Romanos responde a pergunta: Como pode o homem ser justo para com Deus?', null::jsonb, 'C'),
  ('etica-crista-teste-2', 13, 'CERTO_ERRADO', 'A carta aos Gálatas combate o ensino dos judaizantes.', null::jsonb, 'C'),
